<script setup lang="ts">
import {open} from '@tauri-apps/api/dialog'
import Modal from '@/components/ui/Modal.vue'
import {useSourceComparisonStore} from '@/stores/sourceComparison'
const emit=defineEmits<{close:[];queue:[]}>(),comparison=useSourceComparisonStore()
async function choose(){const queued=import.meta.env.VITE_DESKTOP_E2E==='1'?window.__LONG_DECOMPRESS_DESKTOP_E2E__?.takeDesktopDialogSelection():undefined;const path=queued===undefined?await open({directory:true,title:'选择差异取回位置'}):queued;if(typeof path==='string')comparison.options.outputDirectory=path}
</script>
<template>
 <Modal :visible="true" title="取回所选资料" icon="pi pi-download" size="xl" :show-footer="true" :show-close-button="!comparison.busy" :close-on-backdrop="!comparison.busy" :close-on-escape="!comparison.busy" @update:visible="emit('close')">
  <div class="retrieval-grid" data-testid="comparison-retrieval-dialog">
   <section class="card"><h3>本次选择 <span>{{ comparison.selectedCount }} 项</span></h3><p class="note">只处理勾选的文件与空目录，原件保留。来源变化时保留未加入的选择。</p><div class="selection-list custom-scrollbar"><article v-for="side in (['left','right'] as const)" v-show="comparison.selected[side].size" :key="side"><strong>{{ side==='left'?'左侧':'右侧' }} · {{ comparison.sides[side].source?.name }}</strong><p class="note">{{ comparison.selected[side].size }} 项 · {{ comparison.sides[side].source?.source.kind==='zip'?'ZIP 所选提取':'文件夹所选复制' }}</p><p v-if="comparison.issues[side]" class="error" :data-comparison-issue="side">{{ comparison.issues[side] }} <a href="#/compare" class="link" @click="emit('close')">返回处理来源</a></p><details><summary>查看并调整所选路径</summary><div v-for="path in comparison.selected[side]" :key="path" class="selected-path"><span>{{ path }}</span><button class="link" :disabled="comparison.busy" :aria-label="'移除 '+side+' '+path" @click="comparison.toggle(side,path)">移除</button></div></details></article><p v-if="!comparison.selectedCount" class="note">本批已加入原解压中心，可核对后开始取回。</p></div></section>
   <section class="card"><h3>保存方式</h3><fieldset :disabled="comparison.busy" class="fields"><label>取回位置<div class="path-input"><input v-model="comparison.options.outputDirectory" data-testid="comparison-retrieval-output" placeholder="选择或输入保存位置"><button class="button" data-testid="comparison-retrieval-choose-output" @click="choose">选择</button></div></label><label>左右来源<select v-model="comparison.options.separateSides" data-testid="comparison-retrieval-separate"><option :value="true">左右分别放入子目录（推荐）</option><option :value="false">合并到同一个目录</option></select></label><label>文件夹结构<select v-model="comparison.options.keepStructure" data-testid="comparison-retrieval-structure"><option :value="true">保留相对路径</option><option :value="false">放在同一层</option></select></label><label>同名文件<select v-model="comparison.options.conflictPolicy" data-testid="comparison-retrieval-conflict"><option value="rename">自动改名，保留两份</option><option value="skip">跳过已存在项</option></select></label></fieldset><p class="note">来源和所选范围会随任务保留。进入原解压中心查看进度、暂停、停止和实际结果；不覆盖或删除来源。</p></section>
  </div>
  <p v-if="comparison.error" class="error mt-3" role="alert">{{ comparison.error }}</p><p v-if="comparison.notice" class="note mt-3" role="status" data-testid="comparison-retrieval-notice">{{ comparison.notice }}</p>
  <template #footer><button class="button" :disabled="comparison.busy" @click="emit('close')">返回</button><button v-if="comparison.admitted" class="button" :disabled="comparison.busy" data-testid="comparison-retrieval-go-queue" @click="emit('queue')">前往解压中心</button><button class="button primary" :disabled="comparison.busy||!comparison.selectedCount" data-testid="comparison-retrieval-confirm" @click="comparison.queue">{{ comparison.busy?'正在准备…':'将可用部分加入队列' }}</button></template>
 </Modal>
</template>
<style scoped>
.retrieval-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{min-width:0;border:1px solid var(--border-subtle);border-radius:16px;padding:18px;background:var(--bg-card)}h3{font-size:14px;font-weight:900}h3 span{color:var(--dynamic-accent);margin-left:8px}.note,.error{font-size:11px;line-height:1.9;overflow-wrap:anywhere;color:var(--text-muted);margin-top:10px}.error{color:#d97706}.selection-list{max-height:330px;overflow:auto;margin-top:16px}.selection-list article{border:1px solid var(--border-subtle);border-radius:12px;padding:12px;margin-bottom:10px;font-size:12px;overflow-wrap:anywhere}summary{font-size:11px;cursor:pointer;margin-top:10px;color:var(--dynamic-accent)}.selected-path{display:flex;gap:10px;align-items:center;font-size:11px;line-height:1.8;padding-top:8px}.selected-path span{flex:1;min-width:0;overflow-wrap:anywhere}.link{color:var(--dynamic-accent);font-size:11px;flex-shrink:0}.fields{display:flex;flex-direction:column;gap:18px;margin-top:18px}.fields label{font-size:12px;font-weight:700;min-width:0}.fields input,.fields select{width:100%;min-width:0;border:1px solid var(--border-subtle);border-radius:10px;padding:10px 12px;background:var(--bg-input);font-size:12px;margin-top:8px;color:var(--text-content)}.path-input{display:flex;gap:8px;min-width:0;margin-top:8px}.path-input input{flex:1;margin:0}.path-input button{flex-shrink:0}.button{padding:10px 13px;font-size:12px;border-radius:10px;border:1px solid var(--border-subtle);background:var(--bg-input);color:var(--text-content)}.button.primary{background:var(--dynamic-accent);color:white}.button:disabled,.link:disabled{opacity:.45}@media(max-width:800px){.retrieval-grid{grid-template-columns:minmax(0,1fr)}.card{padding:14px}.selection-list{max-height:200px}}
</style>
